window.__S = () => window.__ensemble.getState();
window.__sleep = (ms) => new Promise(r => setTimeout(r, ms));
window.__clicks = 0;
window.__screens = [];
window.__app = 0;
window.__root = () => document.querySelector('.fixed.inset-0.z-40') || document;
window.__btn = (re) => [...window.__root().querySelectorAll('button')].find(b => re.test((b.textContent || '').trim()) && !b.disabled);
window.__click = (re) => { const b = window.__btn(re); if (b) { window.__clicks++; b.click(); } return !!b; };
window.__h1 = () => window.__root().querySelector('h1')?.textContent || '';
window.__titles = () => [...window.__root().querySelectorAll('button .text-\\[14px\\].font-semibold')].map(x => x.textContent).join(' / ');
window.__until = async (f, ms) => { const t = performance.now(); while (performance.now() - t < ms) { if (f()) return performance.now() - t; await window.__sleep(50); } return -1; };
window.__running = () => { const s = window.__S(); if (!s.chatId) return false; const chat = s.chats.find(c => c.id === s.chatId); const k = s.chatId + ':' + (chat?.leadId || s.settings.leadId); const st = s.agents[k]; return !!st && st.phase && st.phase !== 'idle'; };
return 'helpers';
